// src/components/AdminFeeManager.jsx
import React, { useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import Swal from "sweetalert2"; // Added Swal for confirmation/alerts

export default function AdminFeeManager() {
  const [admissionNo, setAdmissionNo] = useState("");
  const [data, setData] = useState(null);
  const [newFeeTitle, setNewFeeTitle] = useState("");
  const [newFeeAmount, setNewFeeAmount] = useState("");
  const [editingKey, setEditingKey] = useState(null);
  const [editAmount, setEditAmount] = useState("");

  // Helper: class-based fee heads (Copied from Parent side)
  const getFeeKeysForClass = (cls) => {
    const c = Number(cls);
    if (c >= 1 && c <= 5) return ["development", "transport"];
    if (c >= 6 && c <= 9) return ["tuition", "development", "transport"];
    return ["exam", "tuition", "development"];
  };

  const fetchFee = async () => {
    if (!admissionNo.trim()) return toast.error("Please enter admission number");
    setData(null); // Clear previous data
    try {
      const res = await axios.get(`http://localhost:5000/api/fees/student/${admissionNo}`);
      if (res.data.success) {
        // Assuming backend response structure matches the Parent code's expectation
        setData(res.data.data);
        toast.success("Record found for fee management!");
      } else toast.error("No record found");
    } catch (err) {
      console.error(err);
      toast.error("Failed to fetch record");
    }
  };

  // --- Core Admin Functionality ---

  const handleUpdateFee = async (key, currentAmount) => {
    setEditingKey(key);
    setEditAmount(currentAmount);
  };

  const saveFeeUpdate = async (key) => {
    const newAmt = Number(editAmount);

    if (!newAmt || newAmt < 0) return toast.error("Enter valid amount (or 0 to waive)");

    // 🚨 FIX: Using the correct Master Fee Update Endpoint
    try {
      const ok = await Swal.fire({
          title: `Update Master Fee: ${key}?`,
          text: `Change amount to ₹${newAmt} for all students in this class?`,
          icon: "warning",
          showCancelButton: true,
          confirmButtonText: "Yes, Update Master Fee",
      });
      if (!ok.isConfirmed) return;

      const res = await axios.put("http://localhost:5000/api/fees/admin/update-master-head", {
        key: key,
        newAmount: newAmt,
      });

      if (res.data.success) {
        toast.success(`Master fee head '${key}' updated successfully!`);
        setEditingKey(null);
        // Re-fetch data to show the updated structure automatically
        await fetchFee(); 
      } else {
        toast.error(res.data.error || "Failed to update master fee head");
      }
    } catch (err) {
      console.error(err);
      toast.error("An error occurred during update");
    }
  };

  const handleAddFeeHead = async () => {
    if (!newFeeTitle.trim() || !Number(newFeeAmount) || Number(newFeeAmount) <= 0) {
      return toast.error("Please enter valid Title and Amount");
    }
    
    const key = newFeeTitle.trim().toLowerCase().replace(/\s+/g, '_');

    // 🚨 FIX: Using the correct Master Fee Add Endpoint
    try {
        const ok = await Swal.fire({
            title: `Add Master Fee: ${newFeeTitle}?`,
            text: `This will be added to the fee structure for all relevant classes.`,
            icon: "info",
            showCancelButton: true,
            confirmButtonText: "Yes, Add Master Fee",
        });
        if (!ok.isConfirmed) return;
        
      const res = await axios.post("http://localhost:5000/api/fees/admin/add-master-head", {
        key: key, 
        title: newFeeTitle.trim(),
        amount: Number(newFeeAmount),
      });

      if (res.data.success) {
        toast.success(`New master fee head "${newFeeTitle}" added successfully!`);
        setNewFeeTitle("");
        setNewFeeAmount("");
        // Re-fetch data to show the updated structure automatically
        await fetchFee(); 
      } else {
        toast.error(res.data.error || "Failed to add fee head");
      }
    } catch (err) {
      console.error(err);
      toast.error("An error occurred while adding fee head");
    }
  };

  // --- UI Rendering ---

  const renderFeeTable = () => {
    if (!data) return null;
    const student = data.student;
    // Note: Assuming fee.items is where the final, computed fee structure resides
    const items = data.fee?.items || {}; 
    const keys = getFeeKeysForClass(student.classApplied || student.class); 
    const paid = data.payments?.reduce((s, t) => s + (t.amount || 0), 0) || 0;
    const total = keys.reduce((s, k) => s + (items[k]?.amount || 0), 0);
    const remaining = Math.max(0, total - paid);

    return (
      <div className="fee-card">
        <h3>{student.studentName} — Class {student.classApplied || student.class}</h3>
        <p>Current Fee Structure for this Class (Managed via Master List)</p>
        
        {/* ⚠️ DOM Warning Fix: Ensure no extra whitespace between <tr> and <th>/<td> tags */}
        <table className="fee-table">
          <thead>
            <tr>
              <th>Particular</th>
              <th>Amount (₹)</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {keys.map((k) => (
              <tr key={k}>
                <td>{items[k]?.title || k}</td>
                <td>
                  {editingKey === k ? (
                    <input
                      type="number"
                      value={editAmount}
                      onChange={(e) => setEditAmount(e.target.value)}
                      style={{ width: '80px', padding: '5px' }}
                    />
                  ) : (
                    `₹${items[k]?.amount?.toLocaleString() || 0}`
                  )}
                </td>
                <td>
                  {editingKey === k ? (
                    <>
                      <button onClick={() => saveFeeUpdate(k)}>Save</button>
                      <button className="secondary-btn" onClick={() => setEditingKey(null)}>Cancel</button>
                    </>
                  ) : (
                    <button onClick={() => handleUpdateFee(k, items[k]?.amount)}>
                      ✏️ Edit Master Amount
                    </button>
                  )}
                </td>
              </tr>
            ))}
            <tr className="fee-total"><td><b>Total Payable</b></td><td colSpan="2"><b>₹{total.toLocaleString()}</b></td></tr>
            <tr><td>Paid Till Date</td><td colSpan="2">₹{paid.toLocaleString()}</td></tr>
            <tr><td>Remaining Balance</td><td colSpan="2">₹{remaining.toLocaleString()}</td></tr>
          </tbody>
        </table>

        {/* Add New Fee Type Section */}
        <div className="add-fee-section" style={{ marginTop: '20px', borderTop: '1px solid #ccc', paddingTop: '15px' }}>
          <h4>➕ Add New Master Fee Type / Head</h4>
          <input
            type="text"
            value={newFeeTitle}
            onChange={(e) => setNewFeeTitle(e.target.value)}
            placeholder="Fee Title (e.g., Annual Charge)"
            style={{ marginRight: '10px' }}
          />
          <input
            type="number"
            value={newFeeAmount}
            onChange={(e) => setNewFeeAmount(e.target.value)}
            placeholder="Amount (₹)"
            style={{ marginRight: '10px' }}
          />
          <button onClick={handleAddFeeHead}>Add Master Fee Type</button>
          <p style={{ fontSize: '12px', color: '#666' }}>
            **Important:** This adds a fee head to the **Master List**. It will appear for this class if its *key* is included in the **`getClassBasedFeeTypes`** helper function.
          </p>
        </div>
      </div>
    );
  };

  return (
    <div className="fee-page">
      <Toaster />
      <div className="fee-container">
        <h2>🧑‍💻 Admin Manage Student Fee Structure</h2>
        <div className="search-box">
          <input
            type="text"
            placeholder="Enter Student Admission No."
            value={admissionNo}
            onChange={(e) => setAdmissionNo(e.target.value)}
          />
          <button onClick={fetchFee}>Fetch Structure</button>
        </div>
        {renderFeeTable()}
      </div>
    </div>
  );
}
